package net.zartra.gui;
import org.bukkit.configuration.*; import org.bukkit.configuration.file.YamlConfiguration; import java.io.*; import java.util.*; import java.util.logging.Logger;
final class MenuStorage { private final File dir; private final Logger log; MenuStorage(File dir,Logger log){this.dir=dir;this.log=log;}
 Map<String,MenuDefinition> load(){Map<String,MenuDefinition> out=new TreeMap<String,MenuDefinition>();if(!dir.exists())dir.mkdirs();File[] fs=dir.listFiles();if(fs==null)return out;for(File f:fs)if(f.getName().endsWith(".yml"))try{YamlConfiguration y=YamlConfiguration.loadConfiguration(f);String id=y.getString("id");if(!MenuManager.validId(id))throw new IOException("unsafe id");MenuDefinition d=new MenuDefinition(id,y.getString("title",id),y.getInt("rows",3));d.openingCommand=y.getString("opening-command","");d.openingPermission=y.getString("opening-permission","");d.permissionDenied=y.getString("permission-denied",d.permissionDenied);d.openingSound=y.getString("opening-sound","");d.closingSound=y.getString("closing-sound","");d.refreshInterval=y.getLong("refresh-interval",0);d.closeAfterAction=y.getBoolean("close-after-action",false);d.createdAt=y.getLong("created-at",d.createdAt);d.modifiedAt=y.getLong("modified-at",d.modifiedAt);d.formatVersion=y.getInt("format-version",1);ConfigurationSection all=y.getConfigurationSection("items");boolean migrated=false;if(all!=null)for(String key:all.getKeys(false)){ConfigurationSection s=all.getConfigurationSection(key);int slot=Integer.parseInt(key);if(s==null||slot<0||slot>=d.rows*9)continue;MenuItem i=new MenuItem(new org.bukkit.inventory.ItemStack(CompatMaterial.find(s.getString("material","STONE")),Math.max(1,s.getInt("amount",1))),(MenuAction.parse(s.getString("action"))));i.material=s.getString("material","STONE");i.data=s.getInt("data",0);i.amount=Math.max(1,Math.min(64,s.getInt("amount",1)));i.name=s.getString("name",null);i.lore=s.getStringList("lore");i.glow=s.getBoolean("glow",false);i.cooldown=s.getLong("cooldown",0);ConfigurationSection acts=s.getConfigurationSection("actions");if(acts!=null)for(String ct:acts.getKeys(false))try{MenuClickType t=MenuClickType.valueOf(ct);for(Map<?,?> raw:acts.getMapList(ct)){ActionEntry a=new ActionEntry();a.id=String.valueOf(raw.get("id"));a.type=String.valueOf(raw.get("type"));a.value=raw.get("value")==null?"":String.valueOf(raw.get("value"));a.order=num(raw.get("order"),0);a.delay=num(raw.get("delay"),0);a.chance=dbl(raw.get("chance"),100);a.enabled=bool(raw.get("enabled"),true);a.stopOnFailure=bool(raw.get("stop-on-failure"),false);Object rawConditions=raw.get("conditions");if(rawConditions instanceof java.util.List)for(Object co:(java.util.List)rawConditions)if(co instanceof java.util.Map)try{java.util.Map cm=(java.util.Map)co;ConditionEntry ce=new ConditionEntry(ConditionEntry.Type.valueOf(String.valueOf(cm.get("type"))),String.valueOf(cm.get("value")));ce.inverted=bool(cm.get("inverted"),false);a.conditions.add(ce);}catch(Exception ignored){}if(MenuAction.parse(a.type+":")!=null&&ActionValidator.chance(a.chance)&&ActionValidator.delay(a.delay))i.actions(t).add(a);}}catch(Exception ignored){}if(i.action!=null){i.migrateLegacy();migrated=true;}d.items.put(slot,i);}out.put(id,d);if(migrated){File bak=new File(f.getParentFile(),f.getName()+".pre-action-migration.bak");if(!bak.exists())copy(f,bak);save(d);}}catch(Exception e){log.warning("Could not load "+f.getName()+": "+e.getMessage());}return out;}
 private static int num(Object x,int d){try{return Integer.parseInt(String.valueOf(x));}catch(Exception e){return d;}}private static double dbl(Object x,double d){try{return Double.parseDouble(String.valueOf(x));}catch(Exception e){return d;}}private static boolean bool(Object x,boolean d){return x==null?d:Boolean.parseBoolean(String.valueOf(x));}private static void copy(File a,File b)throws IOException{InputStream in=new FileInputStream(a);OutputStream out=new FileOutputStream(b);byte[] q=new byte[8192];int n;while((n=in.read(q))>0)out.write(q,0,n);in.close();out.close();}
 void save(MenuDefinition d)throws IOException{if(!dir.exists())dir.mkdirs();YamlConfiguration y=new YamlConfiguration();y.set("format-version",2);y.set("id",d.id);y.set("title",d.title);y.set("rows",d.rows);y.set("opening-command",d.openingCommand);y.set("opening-permission",d.openingPermission);y.set("permission-denied",d.permissionDenied);y.set("opening-sound",d.openingSound);y.set("closing-sound",d.closingSound);y.set("refresh-interval",d.refreshInterval);y.set("close-after-action",d.closeAfterAction);y.set("created-at",d.createdAt);d.modifiedAt=System.currentTimeMillis();y.set("modified-at",d.modifiedAt);for(Map.Entry<Integer,MenuItem> e:d.items.entrySet()){String p="items."+e.getKey();MenuItem i=e.getValue();y.set(p+".material",i.material);y.set(p+".data",i.data);y.set(p+".amount",i.amount);y.set(p+".name",i.name);y.set(p+".lore",i.lore);y.set(p+".glow",i.glow);y.set(p+".cooldown",i.cooldown);for(Map.Entry<MenuClickType,List<ActionEntry>> x:i.actions.entrySet()){List<Map<String,Object>> list=new ArrayList<Map<String,Object>>();for(ActionEntry a:i.actions(x.getKey())){Map<String,Object> z=new LinkedHashMap<String,Object>();z.put("id",a.id);z.put("type",a.type);z.put("value",a.value);z.put("order",a.order);z.put("delay",a.delay);z.put("chance",a.chance);z.put("enabled",a.enabled);z.put("stop-on-failure",a.stopOnFailure);List<Map<String,Object>> cs=new ArrayList<Map<String,Object>>();for(ConditionEntry ce:a.conditions){Map<String,Object> cm=new LinkedHashMap<String,Object>();cm.put("type",ce.type.name());cm.put("value",ce.value);cm.put("inverted",ce.inverted);cs.add(cm);}z.put("conditions",cs);list.add(z);}y.set(p+".actions."+x.getKey().name(),list);}}File tmp=new File(dir,d.id+".tmp"),dst=new File(dir,d.id+".yml");y.save(tmp);if(dst.exists()&&!dst.delete())throw new IOException("replace failed");if(!tmp.renameTo(dst))throw new IOException("rename failed");}boolean delete(String id){File f=new File(dir,id+".yml");return !f.exists()||f.delete();}}